const body = $json.body ?? $json;

if (typeof body.repository !== 'string' || body.repository.length === 0) {
  throw new Error('repository is required');
}

if (typeof body.request !== 'string' || body.request.length < 3) {
  throw new Error('request must contain at least 3 characters');
}

return [{
  json: {
    status: 'starter',
    workflow: 'implementation-plan',
    run_id: String($execution.id),
    contract_version: 1,
    input: body,
    pipeline: [
      'inspect repository structure and conventions',
      'locate affected components',
      'identify dependencies and migration risks',
      'produce ordered implementation steps',
      'define validation and rollback checks',
      'return a compact execution plan'
    ],
    message: 'MCP -> n8n contract is healthy. Add repository-grounding and planning agents before this response node.'
  }
}];
